class Student:
    def __init__(self, name, scores):
        self.name = name
        self.scores = scores

    def average(self):
        return sum(self.scores) / len(self.scores)

    def __str__(self):
        return f"{self.name} (평균 {self.average():.1f})"


n = int(input())
for _ in range(n):
    parts = input().split()
    student = Student(parts[0], [int(x) for x in parts[1:]])
    print(student)
